async function open(opts={}){setSnapshot(opts.snapshot);if(!validSnapshot(S.snapshot)){opts.onNeedPrimary?.();return false;}if(S.pip&&!S.pip.closed){try{S.pip.focus();S.refs?.input?.focus();return true;}catch(_){}}if(!('documentPictureInPicture'in window)||!window.isSecureContext){opts.onUnsupported?.();return false;}const pip=await window.documentPictureInPicture.requestWindow({width:timerVisible()?254:164,height:timerVisible()?94:84,disallowReturnToOpener:false});S.pip=pip;const d=pip.document;d.documentElement.lang='ar';d.documentElement.dir='rtl';d.title='MyTime Quick Copy • SR';d.head.innerHTML='<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>'+css()+'</style>';d.body.innerHTML='<div class="shell"><div id="grid" class="grid"><div class="toolStack"><button id="shot" class="shot" type="button" title="لقطة شاشة — كليك JPG • كليك يمين PNG" aria-label="التقاط لقطة شاشة"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7.25 5.4 8.7 3.8h6.6l1.45 1.6H19a2.25 2.25 0 0 1 2.25 2.25v9.1A2.25 2.25 0 0 1 19 19H5a2.25 2.25 0 0 1-2.25-2.25v-9.1A2.25 2.25 0 0 1 5 5.4h2.25ZM12 8.25a4.35 4.35 0 1 0 0 8.7 4.35 4.35 0 0 0 0-8.7Zm0 1.75a2.6 2.6 0 1 1 0 5.2 2.6 2.6 0 0 1 0-5.2Z"/></svg></button><button id="mode" class="mode" type="button" title="تبديل نوع النسخ">A</button></div><div class="keyword"><input id="q" autocomplete="off" spellcheck="false" placeholder="الاختصار…"></div><button id="sr" class="sr" type="button" title="الرجوع إلى SR"><span class="srText">SR</span><span class="srArrow">↩</span></button><div id="timerPane" class="timer"><button id="timerDisplay" class="timerDisplay" type="button" title="اضغط لإعادة تشغيل التايمر"><span class="timer-main">00:00</span><span class="timer-frac">.00</span></button><button id="timerModeToggle" class="timerModeToggle" type="button" aria-label="تغيير وضع التايمر" aria-controls="timerModeOptions" aria-expanded="false" title="اختيار وضع التايمر"><span class="modeLabel">SW</span><span class="modeChevron">⌄</span></button><div id="timerModeOptions" class="timerModes"><button class="timerModeChip" type="button" data-timer-mode="stopwatch">SW</button><button class="timerModeChip" type="button" data-timer-mode="countdown60">1m</button><button class="timerModeChip" type="button" data-timer-mode="countdown120">2m</button><button class="timerModeChip" type="button" data-timer-mode="clock" title="ساعة الجهاز بالثواني" aria-label="ساعة الجهاز بالثواني">CLOCK</button></div></div><button id="focus" class="focusToggle" type="button" title="إخفاء/إظهار التايمر">‹</button></div><div id="status" class="status">جاهز</div></div>';
 const refs=S.refs={win:pip,grid:d.getElementById('grid'),input:d.getElementById('q'),modeBtn:d.getElementById('mode'),srBtn:d.getElementById('sr'),shotBtn:d.getElementById('shot'),status:d.getElementById('status'),timerPane:d.getElementById('timerPane'),timerDisplay:d.getElementById('timerDisplay'),timerModeToggle:d.getElementById('timerModeToggle'),timerModeButtons:Array.from(d.querySelectorAll('[data-timer-mode]')),focusToggle:d.getElementById('focus')};
 refs.srBtn.addEventListener('click',()=>{try{window.focus();}catch(_){}});refs.modeBtn.addEventListener('click',()=>setMode(mode()==='plus'?'plain':'plus'));refs.focusToggle.addEventListener('click',()=>setTimerVisible(!timerVisible()));refs.timerDisplay.addEventListener('pointerdown',e=>{if(e.button===0)activateTimer();});function showTimerOptions(open,focus=false){const active=!!open;refs.timerPane.classList.toggle('is-choosing',active);refs.timerModeToggle.setAttribute('aria-expanded',String(active));if(active&&focus){(refs.timerModeButtons.find(b=>b.getAttribute('aria-pressed')==='true')||refs.timerModeButtons[0])?.focus();}}
refs.timerModeToggle.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();showTimerOptions(!refs.timerPane.classList.contains('is-choosing'),true);});
d.addEventListener('pointerdown',e=>{if(refs.timerPane.classList.contains('is-choosing')&&!refs.timerPane.contains(e.target))showTimerOptions(false);},true);
d.addEventListener('keydown',e=>{if(e.key==='Escape'&&refs.timerPane.classList.contains('is-choosing')){e.preventDefault();e.stopPropagation();showTimerOptions(false);refs.timerModeToggle.focus();}},true);
for(const b of refs.timerModeButtons)b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();pressTimerMode(b.dataset.timerMode);showTimerOptions(false);refs.input?.focus({preventScroll:true});});refs.input.addEventListener('input',()=>tryCopy(false));refs.input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();tryCopy(true);}else if(e.key==='Escape'){e.preventDefault();pip.close();}});refs.shotBtn.addEventListener('click',()=>captureScreenshot('image/jpeg'));refs.shotBtn.addEventListener('contextmenu',e=>{e.preventDefault();captureScreenshot('image/png');});renderMode();applyTimerVisibility();saveTimer(loadTimer());renderTimer();pip.addEventListener('pagehide',()=>{if(S.pip!==pip)return;S.pip=null;S.refs=null;stopTimerTicker();clearTimeout(S.pendingCopy);S.pendingCopy=null;S.lastValue='';S.busy=false;});requestAnimationFrame(()=>refs.input.focus());return true;}
